import React from 'react'
import {FormattedMessage, FormattedNumber, useIntl} from 'react-intl'
import {
    Stack,
    Text,
    useBreakpointValue
} from '@salesforce/retail-react-app/app/components/shared/ui'
import {useItemVariant} from '@salesforce/retail-react-app/app/components/item-variant'
import {getPriceData} from '@salesforce/retail-react-app/app/utils/product-utils'
import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price'
import {ZimmProductPrice} from '../ui-kits/atoms/zimmProductPrice'

type PricePerItemProps = {
    currency: string
    basePrice?: number
}

const PricePerItem = ({currency, basePrice}: PricePerItemProps) => {
    return (
        <Text fontSize={{base: '12px', lg: '14px'}}>
            <FormattedNumber style="currency" currency={currency} value={basePrice ?? 0} />
            <FormattedMessage
                defaultMessage="ea"
                id="price_per_item.label.each"
                description="Abbreviated 'each', follows price per item, like $10/ea"
            />
        </Text>
    )
}

type ItemPriceProps = {
    currency: string
    align?: string
    baseDirection?: string
    [key: string]: unknown
}

/**
 * In the context of a cart product item variant, this component renders the item's
 * pricing, taking into account applied discounts as well as base item prices.
 * When an item-level promotion reduces the price, the original price is shown
 * crossed out beside the discounted current price.
 */
const ItemPrice = ({currency, align = 'right', baseDirection = 'column', ...props}: ItemPriceProps) => {
    const variant = useItemVariant() as Record<string, unknown>
    const price = variant?.price as number | undefined
    const priceAfterItemDiscount = variant?.priceAfterItemDiscount as number | undefined
    const priceAfterOrderDiscount = variant?.priceAfterOrderDiscount as number | undefined
    const isASet = (variant?.type as Record<string, unknown> | undefined)?.set as boolean | undefined
    const isMaster = (variant?.type as Record<string, unknown> | undefined)?.master as boolean | undefined
    const quantity = ((variant?.quantity as number | undefined) ?? 1)

    // Use the most-discounted price as the displayed current price: after all order-level
    // adjustments if available, otherwise after item-level adjustments.
    const effectiveCurrentPrice = priceAfterOrderDiscount ?? priceAfterItemDiscount ?? price ?? 0
    const isOnSale = (price ?? 0) > effectiveCurrentPrice

    let priceData
    if (variant?.itemId) {
        priceData = {
            currentPrice: effectiveCurrentPrice,
            // Show the original price crossed out when any promotion (item- or order-level) has
            // reduced the price. The base SFCC component sets listPrice: null to suppress this.
            listPrice: isOnSale ? price : null,
            // Divide effectiveCurrentPrice (after all discounts) by quantity rather than using
            // variant.pricePerUnit, which SFCC computes from the original list price and would
            // show the wrong per-unit value when an order-level discount is applied.
            pricePerUnit: quantity > 0 ? effectiveCurrentPrice / quantity : effectiveCurrentPrice,
            isASet,
            isMaster,
            isRange: isASet || isMaster || false,
            isOnSale
        }
    } else {
        priceData = getPriceData(variant)
    }
    const isDesktop = useBreakpointValue({base: false, lg: true})
    const intl = useIntl()

    return (
        <Stack
            textAlign={align}
            direction={baseDirection}
            justifyContent={align === 'left' ? 'flex-start' : 'flex-end'}
            alignItems="baseline"
            spacing={priceData?.isOnSale ? 0 : 1}
            wrap="nowrap"
            {...props}
        >
            {!isDesktop && quantity > 1 && !isASet && priceData?.pricePerUnit && (
                <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
            )}

            {variant?.itemId && isOnSale ? (
                // ZimmProductPrice already owns the Was/Now label treatment — reuse it rather
                // than duplicating the label strings and styling. Prices are formatted here
                // because ZimmProductPrice expects pre-formatted strings, not raw numbers.
                <ZimmProductPrice
                    currentPrice={intl.formatNumber(effectiveCurrentPrice, {style: 'currency', currency})}
                    originalPrice={intl.formatNumber(price ?? 0, {style: 'currency', currency})}
                    isLive={true}
                />
            ) : variant?.itemId ? (
                <DisplayPrice
                    labelForA11y={variant?.name as string}
                    currency={currency}
                    priceData={priceData}
                    listPriceProps={{fontSize: 'sm'}}
                />
            ) : (
                <DisplayPrice
                    labelForA11y={variant?.name as string}
                    currency={currency}
                    priceData={priceData}
                    quantity={variant?.quantity as number}
                    listPriceProps={{fontSize: 'sm'}}
                />
            )}

            {isDesktop && quantity > 1 && !isASet && priceData?.pricePerUnit && (
                <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
            )}
        </Stack>
    )
}

export default ItemPrice

