import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmBadge } from 'app/components/ui-kits/atoms/zimmBadge';

/** Design-confirmed cap on how many badges render at once — SFCC-132 Jira thread (Kiera,
 *  2026-09-07): "Let's run with 2! I'll add in the optionality in the Design System." */
const MAX_BADGES = 2;

/** One product badge as the molecule expects it — pre-mapped from the raw SFCC shape
 *  (c_productBadges' productBadge/productBadgeUrl). See .docs/prd/pdp.md §3. */
export type ProductBadge = {
  /** Badge label, e.g. "Campaign". */
  label: string;
  /** Filtered-PLP category URL. Badges without one render non-interactive (see ZimmBadge). */
  href?: string;
};

type ZimmProductBadgesProps = {
  /**
   * Badges in priority order. SCAPI pre-sorts `c_productBadges` by badgePriorityOrder, so this
   * component only caps the count at MAX_BADGES — it does not re-sort.
   */
  badges?: ProductBadge[];
};

/**
 * Molecule — row of up to MAX_BADGES product badges (Campaign, Runway, Exclusive, Online
 * Exclusive, VIC Exclusive). Renders nothing when there are no badges to show.
 *
 * @param props see ZimmProductBadgesProps
 * @returns the badge row, or null when `badges` is empty/absent
 */
export const ZimmProductBadges = ({ badges = [] }: ZimmProductBadgesProps) => {
  const styles = useMultiStyleConfig('ZimmProductBadges', {});

  if (badges.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.row}>
      {badges.slice(0, MAX_BADGES).map((badge) => (
        <ZimmBadge key={badge.label} label={badge.label} href={badge.href} />
      ))}
    </chakra.div>
  );
};

