/**
 * Tests the cart item price branching logic added in SFCC-645/SFCC-778:
 *   - order-level promotions (priceAfterOrderDiscount) trigger Was/Now via ZimmProductPrice
 *   - item-level promotions (priceAfterItemDiscount) trigger Was/Now via ZimmProductPrice
 *   - order-level discount takes precedence over item-level when both are present
 *   - no discount renders DisplayPrice without Was/Now
 *   - no itemId (wishlist variant) renders DisplayPrice without Was/Now
 *
 * ZimmProductPrice and DisplayPrice are stubbed so assertions target this component's own
 * branching contract, not those atoms' rendering.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';

vi.mock('@salesforce/retail-react-app/app/components/item-variant', () => ({
    useItemVariant: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async () => {
    const actual = await vi.importActual<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>(
        '@salesforce/retail-react-app/app/components/shared/ui',
    );
    return { ...actual, useBreakpointValue: vi.fn(() => false) };
});

vi.mock('@salesforce/retail-react-app/app/components/display-price', () => ({
    default: ({ priceData }: { priceData?: { currentPrice?: number } }) => (
        <div data-testid="display-price">{priceData?.currentPrice}</div>
    ),
}));

vi.mock('../ui-kits/atoms/zimmProductPrice', () => ({
    ZimmProductPrice: ({
        currentPrice,
        originalPrice,
    }: {
        currentPrice?: string;
        originalPrice?: string;
    }) => (
        <div data-testid="zimm-product-price">
            <span data-testid="current-price">{currentPrice}</span>
            <span data-testid="original-price">{originalPrice}</span>
        </div>
    ),
}));

vi.mock('@salesforce/retail-react-app/app/utils/product-utils', () => ({
    getPriceData: vi.fn(() => ({ currentPrice: 100 })),
}));

import { useItemVariant } from '@salesforce/retail-react-app/app/components/item-variant';
import ItemPrice from './item-price';

const mockedUseItemVariant = vi.mocked(useItemVariant);

const renderItemPrice = () =>
    render(
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
            <ItemPrice currency="AUD" />
        </IntlProvider>,
    );

const baseVariant = {
    itemId: 'item-001',
    productId: 'prod-001',
    name: 'Test Product',
    price: 300,
    quantity: 1,
    type: {},
};

beforeEach(() => {
    vi.clearAllMocks();
